// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount1 = bound(amount1, 1, 10 ether);
        amount2 = bound(amount2, 1, 10 ether);

        vm.deal(actor, amount1 + amount2);

        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount1 + amount2, "deposits must accumulate in caller's recorded balance");
    }
}
